/// <summary>@ensurevars — 없는 회차 변수를 기본값으로 채운다(0.4.0 이전 저장 호환). 하루 흐름 맨 앞에서 부른다.</summary>
[Alias("ensurevars")]
public class EnsureVarsCommand : Command
{
#pragma warning disable CS1998
    public override async Awaitable Execute (ExecutionContext ctx)
#pragma warning restore CS1998
    {
        var vars = Engine.GetServiceOrErr<ICustomVariableManager>();
        foreach (var n in MolakVarList.Nums) if (!vars.VariableExists(n)) vars.SetVariableValue(n, new CustomVariableValue(0f));
        foreach (var n in MolakVarList.Strings) if (!vars.VariableExists(n)) vars.SetVariableValue(n, new CustomVariableValue("none"));
        if (MolakStats.Get("raidday") < 1f) MolakStats.Set("raidday", 42f);
        if (MolakStats.Get("thday") < 1f) MolakStats.Set("thday", 999f);
    }
}
